import 'package:flutter/material.dart';
import '../models/field_definition.dart';
class DynamicFieldInput extends StatelessWidget { const DynamicFieldInput({super.key, required this.field, required this.controller}); final FieldDefinition field; final TextEditingController controller; @override Widget build(BuildContext context) { if (field.type == 'enum') return DropdownButtonFormField<String>(value: controller.text.isEmpty ? null : controller.text, decoration: InputDecoration(labelText: field.label), items: (field.options ?? const []).map((o) => DropdownMenuItem(value: o, child: Text(o))).toList(), onChanged: (v) => controller.text = v ?? ''); return TextFormField(controller: controller, maxLines: field.type == 'textarea' ? 4 : 1, keyboardType: ['number','phone'].contains(field.type) ? TextInputType.number : field.type == 'email' ? TextInputType.emailAddress : TextInputType.text, decoration: InputDecoration(labelText: field.label, suffixIcon: field.sensitive ? const Icon(Icons.lock) : null), validator: (v) => field.mandatory && (v == null || v.trim().isEmpty) ? 'Required' : null); }}
